import { Product } from '../entities/Product';
import { Order } from '../entities/Order';

export class StockManager {
  canReserveStock(products: Product[], order: Order): boolean {
    for (const line of order.lines) {
      const product = products.find(p => p.id === line.productId);
      if (!product || !product.canReserve(line.quantity)) {
        return false;
      }
    }
    return true;
  }

  reserveStock(products: Product[], order: Order): void {
    for (const line of order.lines) {
      const product = products.find(p => p.id === line.productId);
      if (product) {
        product.reserve(line.quantity);
      }
    }
  }

  releaseStock(products: Product[], order: Order): void {
    for (const line of order.lines) {
      const product = products.find(p => p.id === line.productId);
      if (product) {
        product.release(line.quantity);
      }
    }
  }
}

